style.css:
@-moz-document url("https://www.youtube.com/") {
/* Основной фон страницы - изображение */
  body {
    background: url("https://images.unsplash.com/photo-1506744038136-46273834b3fb") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Темная полупрозрачная накладка для читаемости */
  #container, ytd-app, ytd-page-manager, ytd-masthead, ytd-watch-flexy {
    background: rgba(0, 0, 0, 0.6) !important;
  }

  /* Изменение цвета текста и элементов для контраста */
  * {
    color: #fff !important;
  }

  /* Удаление лишних элементов, чтобы fokus был на видео и интерфейсе */
  ytd-rich-item-renderer,
  ytd-video-renderer {
    background-color: rgba(0, 0, 0, 0.4) !important;
    border-radius: 8px;
    margin-bottom: 10px;
  }
}
